/* Run detail, Activity, Insights, and the shared read-only pipeline diagram. */
const STAGES = [
  { id: 'trigger', label: 'Start', sub: 'three ways to start', kind: 'code', x: 20, y: 24, level: 1, what: 'A round starts in three ways only: the PR becomes ready for review in GitHub, someone clicks Start review, or the factory pushed its own fix and that commit is still the head. A push by a person starts nothing.', tools: '—', prompt: '—', schema: 'round number, head SHA, review level (frozen for the round)', timeout: '—', attempts: '—' },
  { id: 'checks', label: 'Checks', sub: 'code', kind: 'code', x: 170, y: 24, level: 2, what: 'Fetches the branch, reads CI results, runs the install command and lists the sensitive files the PR changes.', tools: 'git, GitHub API, install command', prompt: '—', schema: 'diff, CI counts, sensitive files, changed packages', timeout: '10 min', attempts: '3, with backoff' },
  { id: 'task', label: 'Task', sub: 'code', kind: 'code', x: 320, y: 24, level: 2, what: 'Finds the ClickUp task for the PR from the branch name, the PR text or a linked task.', tools: 'ClickUp API', prompt: '—', schema: 'task id, title, description', timeout: '1 min', attempts: '3, with backoff' },
  { id: 'type', label: 'Change type', sub: 'rules + judge', kind: 'agent', role: 'judge', x: 470, y: 24, level: 2, what: 'Rules on paths and size set the floor. The judge may only raise it. Types: Uses existing parts, Changes behaviour, One-way door.', tools: 'none (reads the brief only)', prompt: 'classify-rules.md', schema: 'change type, rule that fired', timeout: '2 min', attempts: '2' },
  { id: 'review', label: 'Review', sub: 'reviewer', kind: 'agent', role: 'reviewer', x: 620, y: 24, level: 1, what: 'Reads the diff, the task and the code around the change. Writes findings and questions within the limits of the level.', tools: 'Read, Grep, Glob (read-only)', prompt: 'review-rules.md, lessons.md, repo-knowledge.md', schema: 'up to 7 findings, questions with 2–3 options and a recommendation', timeout: '30 min', attempts: '1 (a retry is a button, not automatic)' },
  { id: 'verify', label: 'Verify', sub: 'verifier, each finding', kind: 'agent', role: 'verifier', x: 770, y: 24, level: 3, what: 'Checks each finding without seeing the proposed fix. Quotes must exist word for word. A reproduction script runs in a sandbox; its result beats the agent\'s verdict.', tools: 'Read, Grep, sandboxed script', prompt: 'verify-rules.md', schema: 'verdict, reason, evidence quotes, reproduction (exit code, output)', timeout: '5 min per script', attempts: '1 + 1 repair of the script' },
  { id: 'decide', label: 'Decide', sub: 'people', kind: 'human', x: 920, y: 24, level: 1, what: 'People answer questions, give opinions, decide each finding and approve sensitive files. Every decision is signed.', tools: '—', prompt: '—', schema: 'answers, opinions, decisions, approval', timeout: 'waits', attempts: '—' },
  { id: 'impl', label: 'Implement', sub: 'implementer', kind: 'agent', role: 'implementer', x: 470, y: 118, level: 4, what: 'Fixes the findings marked Implement in a separate copy of the branch. Edit only, no shell. At level 5 it starts by itself when every autofix condition holds.', tools: 'Read, Edit (no shell)', prompt: 'implement-rules.md', schema: 'patch, list of fixed findings', timeout: '15 min', attempts: '1' },
  { id: 'repro', label: 'Reproductions', sub: 'code', kind: 'code', x: 620, y: 118, level: 4, what: 'Runs every reproduction that showed a bug again, now on the patched code. All must pass.', tools: 'sandboxed scripts', prompt: '—', schema: 'pass or fail per reproduction', timeout: '5 min per script', attempts: '1' },
  { id: 'push', label: 'Push', sub: 'person or autofix', kind: 'human', x: 770, y: 118, level: 4, what: 'A person reads the diff and pushes it (PR number and signature). At level 5 the factory pushes by itself, unless the patch touches a sensitive file. Never forced.', tools: 'git push', prompt: '—', schema: 'pushed commit SHA', timeout: 'waits', attempts: '—' },
  { id: 'fixcheck', label: 'Fix check', sub: 'rounds 2–3', kind: 'agent', role: 'reviewer', x: 920, y: 118, level: 4, what: 'Starts only when the head is exactly the factory\'s own commit. Reads the diff since the last round and checks whether each finding marked Implement is resolved.', tools: 'Read, Grep, sandboxed script', prompt: 'review-rules.md', schema: 'resolved or not resolved per finding', timeout: '15 min', attempts: '1' },
  { id: 'merge', label: 'Merge', sub: 'person', kind: 'human', x: 1070, y: 24, level: 1, what: 'Squash merge pinned to the reviewed commit. The merge checklist is checked again from fresh GitHub state at the click.', tools: 'GitHub API', prompt: '—', schema: 'merge commit', timeout: '—', attempts: '—' },
  { id: 'learn', label: 'Analyst', sub: 'after close', kind: 'agent', role: 'analyst', x: 1070, y: 118, level: 6, what: 'After a PR closes, reads the case (findings, verdicts, decisions, human comments) and proposes up to 5 lessons. A person accepts every lesson.', tools: 'none (reads the case only)', prompt: 'analyst-rules.md', schema: 'lesson candidates: rule, why, source PRs', timeout: '5 min', attempts: '2' }
];
const PIPE_EDGES = ['M152,46 H170', 'M302,46 H320', 'M452,46 H470', 'M602,46 H620', 'M752,46 H770', 'M902,46 H920', 'M1052,46 H1070', 'M950,68 V94 H535 V118', 'M602,140 H620', 'M752,140 H770', 'M902,140 H920', 'M1010,118 V68', 'M1136,68 V118'];
function PipelineSvg({ onPick, sel, marks, compact }) {
  return html`<div class="overflow-x-auto"><svg viewBox="0 0 1222 ${compact ? 178 : 206}" style=${{ minWidth: '900px', width: '100%' }} role="img" aria-label="Pipeline diagram: stages of a review round, the fix loop, merge and learning">
    <defs><marker id="arr" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="var(--border-strong)" /></marker></defs>
    ${PIPE_EDGES.map(d => html`<path d=${d} class="pipe-edge" marker-end="url(#arr)" />`)}
    <text x="740" y="88" class="pipe-lane" text-anchor="middle">decided Implement</text><text x="1014" y="98" class="pipe-lane">back to Decide</text>
    ${STAGES.map(s => { const m = marks && marks[s.id]; return html`<g class=${cx('pipe-node', s.kind, sel === s.id && 'sel', m)} transform=${'translate(' + s.x + ',' + s.y + ')'} tabindex=${onPick ? 0 : null} role=${onPick ? 'button' : null} aria-label=${s.label + ', ' + s.sub + ', from level ' + s.level} onClick=${onPick ? () => onPick(s.id) : null} onKeyDown=${onPick ? e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onPick(s.id); } } : null}>
      <rect width="132" height="44" rx="8" /><text x="12" y="19">${s.label}</text><text x="12" y="34" class="sub">${s.sub}</text>
      <text x="122" y="17" class="sub" text-anchor="end">L${s.level}+</text></g>`; })}
    ${!compact && html`<g transform="translate(20,186)"><rect width="12" height="12" rx="3" fill="var(--surface-2)" stroke="var(--border-strong)" /><text x="18" y="10" class="pipe-lane" style="font-weight:400">code</text><rect x="70" width="12" height="12" rx="3" fill="var(--surface)" stroke="var(--border-strong)" /><text x="88" y="10" class="pipe-lane" style="font-weight:400">agent</text><rect x="146" width="12" height="12" rx="3" fill="var(--warn-bg)" stroke="var(--warn-line)" /><text x="164" y="10" class="pipe-lane" style="font-weight:400">a person acts</text><text x="270" y="10" class="pipe-lane" style="font-weight:400">L2+ = runs from review level 2 up</text></g>`}
  </svg></div>`;
}

function stageOutput(pr, r, s) {
  const kv = (k, v) => html`<dt>${k}</dt><dd>${v}</dd>`;
  if (s.state === 'off') return html`<p class="text-sm text-ink3 m-0">Off at level ${r.level}. ${s.label} turns on at level ${s.k === 'verify' ? 3 : 2}.</p>`;
  if (s.state === 'pending') return html`<p class="text-sm text-ink3 m-0">Not run${r.status === 'failed' ? ': an earlier stage failed' : ' yet'}.</p>`;
  if (s.state === 'failed') return html`<div class="text-sm"><p class="m-0 text-bad font-medium">Timed out after 30 min. The cost up to the timeout is recorded.</p>${pr.failed && html`<div class="codeblk mt-2"><pre>${pr.failed.detail}</pre></div>`}</div>`;
  if (s.state === 'active') return html`<p class="text-sm text-ink2 m-0">Running now${s.units ? ': ' + s.unit.replace('%d', s.du).replace('%d', s.units) : ''}. Output appears when the stage finishes.</p>`;
  const fs = pr.findings;
  switch (s.k) {
    case 'checks': return html`<dl class="kv">${kv('CI in GitHub', '14 of 14 checks green')}${kv('Install', html`<span class="mono">${S.repos[pr.repo].install}</span> · ok${pr.fork ? ' (skipped for forks)' : ''}`)}${kv('Diff', plural(pr.files, 'file') + ' · +' + pr.add + ' −' + pr.del)}${kv('Sensitive files', pr.sensitive ? pr.sensitive.files.map(f => f.path).join(', ') : 'none changed')}</dl>`;
    case 'task': return html`<dl class="kv">${kv('ClickUp task', pr.clickup ? pr.clickup + ' · found from the branch name' : 'none found in the PR text, the branch name or linked tasks')}</dl>`;
    case 'type': return html`<dl class="kv">${kv('Change type', pr.ctype || 'Changes behaviour')}${kv('Rule that fired', pr.ctype === 'Uses existing parts' ? 'only docs, tests or composition of existing APIs' : 'touches source under packages/ or apps/; ' + (pr.add + pr.del) + ' changed lines')}${kv('Judge', 'did not raise the type')}</dl>`;
    case 'review': return html`<div class="text-sm"><p class="m-0 mb-2">${r.summary || 'Finished.'}</p>${fs.length > 0 && html`<ul class="m-0 pl-4 grid gap-1">${fs.map(f => html`<li>${md(f.title)} <span class="mono text-ink3">${f.file.split('/').pop()}:${f.line}</span></li>`)}</ul>`}</div>`;
    case 'verify': return html`<ul class="m-0 p-0 list-none grid gap-1 text-sm">${fs.map(f => html`<li class="flex items-start gap-2"><${VerdictBadge} f=${f} level=${r.level} /><span class="min-w-0">${md(f.title)}</span></li>`)}</ul>`;
    case 'diff': return html`<dl class="kv">${kv('Compared', html`<span class="mono">${r.sha}</span> with the previous round`)}${kv('Changed files', pr.patch ? pr.patch.files.map(f => f.path).join(', ') : '—')}</dl>`;
    case 'fixes': return html`<ul class="m-0 p-0 list-none grid gap-1 text-sm">${fs.filter(f => f.decision && f.decision.v === 'implement').map(f => html`<li class="flex items-start gap-2"><${Badge} tone=${f.resolved === false ? 'red' : 'green'}>${f.resolved === false ? 'Not resolved' : 'Resolved'}</${Badge}><span>${md(f.title)}</span></li>`)}</ul>`;
    case 'repro': return html`<p class="text-sm m-0">Every reproduction that showed a bug was run again on the new code. ${r.summary}.</p>`;
    default: return html`<p class="text-sm text-ink3 m-0">${s.note || 'Finished.'}</p>`;
  }
}
function transcript(pr, r) {
  const files = pr.findings.map(f => f.file).slice(0, 5), big = r.status === 'failed';
  const rev = { name: r.kind === 'fixcheck' ? 'Reviewer · fix check' : 'Reviewer', model: (S.levels[r.level] && S.levels[r.level].models && S.levels[r.level].models.reviewer) || S.models.reviewer, turns: big ? 211 : 20 + pr.files, filesRead: big ? 163 : pr.files + 3, searches: big ? 48 : 6 + Math.round(pr.files / 3), errors: big ? 2 : 1, cost: big ? null : (r.steps.find(s => s.k === 'review' || s.k === 'fixes') || {}).cost,
    steps: [['read', 'diff.patch', plural(pr.files, 'file') + ', +' + pr.add + ' −' + pr.del], ['read', 'task.md', pr.clickup || 'no task'], ['search', '"' + ((pr.title.match(/: (.*)/) || [0, pr.title])[1].split(' ').slice(0, 2).join(' ')) + '"', '14 matches in 6 files']].concat(files.map(f => ['read', f, 'whole file'])).concat([['error', 'Read ' + (files[0] || 'src/index.ts').replace(/\.[a-z]+$/, '.test.tsx'), 'File not found. Continued without it.']]).concat(big ? [['read', 'packages/ui/src/components/node/node-panel/node-panel.tsx', 'turn 211'], ['error', 'Session stopped', 'Killed at the 30 min stage timeout.']] : [['write', 'result', r.summary]]) };
  const ver = r.level >= 3 && r.kind !== 'fixcheck' && !big ? pr.findings.map(f => ({ name: 'Verifier · finding ' + f.id, model: S.models.verifier, turns: 9 + f.id * 2, filesRead: 3 + (f.evidence ? f.evidence.length : 0), searches: 2, errors: f.repro && f.repro.exit === 1 ? 1 : 0, cost: 0.18,
    steps: [['read', f.file, 'around line ' + f.line], ['search', '"' + f.file.split('/').pop().split('.')[0] + '"', 'usages'], f.repro ? ['run', f.repro.cmd, 'exit ' + f.repro.exit] : ['read', (f.evidence && f.evidence[0] ? f.evidence[0].file : f.file), 'evidence'], ['write', 'verdict', (VERDICTS[f.verdict] || { t: 'Unchecked' }).t]] })) : [];
  return [rev].concat(ver);
}
function RunPage({ route }) {
  const info = getRunInfo(route.path[1]), [open, setOpen] = useState({}), tab = route.q.tab || 'stages';
  if (!info) return html`<main class="gutter py-10"><${Empty} icon="search-x" title="Run not found">It may have been removed by a demo reset. <a class="link" href="#/activity">Open Activity</a></${Empty}></main>`;
  const { pr, r, live } = info, ses = transcript(pr, r);
  const marks = {}; const map = { checks: 'checks', task: 'task', type: 'type', review: 'review', verify: 'verify', fixes: 'fixcheck', diff: 'fixcheck', repro: 'repro' };
  r.steps.forEach(s => { const id = map[s.k]; if (id) marks[id] = s.state === 'done' ? 'ran' : s.state === 'active' ? 'live' : s.state === 'failed' ? 'fail' : 'skip'; }); marks.trigger = 'ran';
  STAGES.forEach(s => { if (!marks[s.id]) marks[s.id] = 'skip'; });
  const files = Array.from(new Set(S.instructions.filter(f => f.scope === 'global' || f.repo === pr.repo || f.level === r.level).map(f => f)));
  const kindIcon = { read: 'file-text', search: 'search', error: 'circle-alert', run: 'terminal', write: 'pen-line' };
  return html`<main class="gutter pb-24">
    <${PageHead} crumbs=${[{ label: 'Pull requests', to: 'prs' }, { label: '#' + pr.num + ' ' + pr.title.slice(0, 48) + (pr.title.length > 48 ? '…' : ''), to: 'pr/' + pr.num }, { label: 'Round ' + r.n }]} title=${'Round ' + r.n + ' of 3' + (r.kind === 'fixcheck' ? ' · fix check' : '') + ' on #' + pr.num}
      sub=${html`<span class="metaline">${[r.status === 'failed' ? html`<span class="text-bad font-medium">Failed, not counted</span>` : live ? html`<span class="inline-flex items-center gap-1.5 text-brandt font-medium"><span class="pulse-dot"></span>${r.status === 'queued' ? 'Queued' : 'Running'}</span>` : html`<span>Finished <${Time} t=${r.at} /></span>`,
        html`started by ${r.by === 'bot' ? 'Factory bot' : r.by === 'hand' ? 'hand' : actorName(r.by)}${r.reason && r.by === 'bot' ? ' · ' + r.reason : ''}`, html`<span class="mono">${r.sha}</span>`, 'level ' + r.level,
        html`<span class="num text-ink font-medium">${r.status === 'failed' ? (r.cost ? money(r.cost) + ' up to the failure' : 'no cost recorded') : money(r.cost) + (live ? ' so far' : '')}</span>`, html`<span class="num">${dur(r.dur)}</span>`].map((m, i) => html`${i > 0 && html`<span class="sep">·</span>`}<span>${m}</span>`)}</span>`} />
    <section class="card mb-4"><div class="card-h"><h2 class="card-t m-0">Where this run went<${Info} pos="right" tip="Green ran · blue is running · red failed · faded did not run in this round." /></h2><a class="link text-xs" href="#/settings/pipeline">Open Pipeline</a></div><div class="px-3 pt-3 pb-1"><${PipelineSvg} compact marks=${marks} /></div></section>
    <div class="prgrid">
      <div class="min-w-0">
        <${Tabs} label="Run sections" value=${tab} onChange=${t => setQ({ tab: t })} tabs=${[{ id: 'stages', label: 'Stages', icon: 'list' }, { id: 'transcript', label: 'Agent transcript', icon: 'bot' }]} />
        ${tab === 'stages' ? html`<div class="card mt-4 divide" role="tabpanel">${r.steps.map((s, i) => { const o = open[i] == null ? (s.state === 'failed' || s.state === 'active' || s.k === 'review' || s.k === 'fixes') : open[i]; const stg = STAGES.find(x => x.id === map[s.k]) || {};
          return html`<div><button class="flex items-center gap-3 w-full px-4 py-3 bg-transparent border-0 text-left cursor-pointer hover:bg-sunk" aria-expanded=${String(o)} onClick=${() => setOpen(Object.assign({}, open, { [i]: !o }))}>
            <${Icon} n=${{ done: 'circle-check', active: 'loader-circle', pending: 'circle', off: 'circle-off', failed: 'circle-x' }[s.state]} s=${16} cls=${cx(s.state === 'done' && 'text-ok', s.state === 'failed' && 'text-bad', s.state === 'active' && 'text-brandt spin', (s.state === 'off' || s.state === 'pending') && 'text-ink4')} />
            <span class="font-medium w-32">${s.label}</span><span class="text-xs text-ink3">${stg.kind === 'agent' ? 'agent · ' + S.models[stg.role] : 'code'}${s.reused ? ' · reused' : ''}</span>
            <span class="flex-1"></span><span class="num text-sm text-ink3">${s.state === 'off' ? 'off at level ' + r.level : s.state === 'pending' ? '—' : dur(s.real)}</span><span class="num text-sm w-14 text-right">${s.cost ? money(s.cost) : '—'}</span><${Icon} n=${o ? 'chevron-up' : 'chevron-down'} s=${15} cls="text-ink3" /></button>
            ${o && html`<div class="px-4 pb-4 pl-[44px]">${stageOutput(pr, r, s)}</div>`}</div>`; })}</div>`
        : html`<div class="grid gap-3 mt-4" role="tabpanel">${ses.map(se => html`<section class="card overflow-hidden"><div class="card-h flex-wrap"><div class="flex items-center gap-2"><${Avatar} a="bot" s=${22} /><span class="card-t">${se.name}</span><span class="mono text-ink3">${se.model}</span></div>
            <div class="flex items-center gap-3 text-xs text-ink2 num flex-wrap"><span>${se.turns} turns</span><span>${se.filesRead} files read</span><span>${se.searches} searches</span><span class=${se.errors ? 'text-bad' : ''}>${plural(se.errors, 'error')}</span><span class="font-semibold text-ink">${se.cost == null ? 'no cost recorded' : money(se.cost)}</span></div></div>
          <ol class="m-0 p-0 list-none divide">${se.steps.map(([k, what, note]) => html`<li class="flex items-start gap-2.5 px-3.5 py-2 text-sm"><${Icon} n=${kindIcon[k]} s=${14} cls=${cx('mt-0.5', k === 'error' ? 'text-bad' : 'text-ink3')} /><span class="w-14 text-xs text-ink3 pt-0.5">${k}</span><span class="mono flex-1 break-all">${what}</span><span class=${cx('text-xs text-right max-w-[40%]', k === 'error' ? 'text-bad' : 'text-ink3')}>${note}</span></li>`)}</ol></section>`)}</div>`}
      </div>
      <aside class="prside">
        <${SideCard} id="rs-cost" title=${html`Cost per session<${Info} pos="right" tip="Code stages cost nothing. Only agent sessions are billed." />`} right=${html`<span class="num font-semibold text-sm">${r.status === 'failed' ? '—' : money(r.cost)}</span>`}><ul class="m-0 p-0 list-none divide">${ses.map(se => html`<li class="flex items-center justify-between gap-2 px-3.5 py-2 text-sm"><span class="trunc">${se.name}</span><span class="num text-ink2">${se.cost == null ? 'not recorded' : money(se.cost)}</span></li>`)}</ul></${SideCard}>
        <${SideCard} id="rs-ver" title=${html`Instruction versions<${Info} pos="right" tip="Frozen when the round starts." />`}><ul class="m-0 p-0 list-none divide">${files.map(f => html`<li class="flex items-center justify-between gap-2 px-3.5 py-2 text-sm"><a class="link mono" href=${'#/settings/instructions/' + f.id}>${f.name}</a><span class="text-xs text-ink3">${f.scope === 'level' ? 'level ' + f.level + ' copy · ' : f.scope === 'repo' ? 'repo · ' : ''}v${f.active}</span></li>`)}</ul></${SideCard}>
      </aside>
    </div>
  </main>`;
}

/* Activity: is anything broken or stuck right now? Alerts first, then one In progress table; history is collapsed. */
function ActivityPage() {
  const prs = Object.values(S.prs);
  const running = prs.filter(p => p.run && !p.run.queued), queued = prs.filter(p => p.run && p.run.queued), jobs = S.jobs.filter(j => !j.queued);
  const starter = by => html`<${Who} a=${by} />`;
  const kind = r => r.kind === 'fix' ? 'Implementer' : r.kind === 'fixcheck' ? 'Round ' + r.n + ' of 3 · fix check' : r.kind === 'retry' ? 'Round ' + r.n + ' of 3 · retry' : 'Round ' + r.n + ' of 3';
  const today = S.activity.filter(a => Date.now() - a.at < DAY), n = running.length + queued.length + jobs.length;
  const prCell = p => html`<a class="link font-medium" style="color:var(--text)" href=${'#/pr/' + p.num}>${p.title}</a> <span class="mono text-ink3">#${p.num}</span>`;
  return html`<main class="gutter pb-24"><${PageHead} title="Activity" />
    <div class="grid gap-5">
      <${AlertsSection} />
      <section aria-labelledby="act-run"><h2 class="sec-t m-0 mb-2 flex items-center gap-2" id="act-run">In progress ${n > 0 && html`<span class="count">${n}</span>`}</h2>
        ${n === 0 ? html`<div class="strip bg-surface text-ink3">No agent is working and nothing is queued.</div>` : html`<div class="tblwrap"><table class="tbl"><thead><tr><th>Pull request</th><th>Run</th><th style="width:32%">Progress</th><th>Started by</th><th class="r">Spent</th><th></th></tr></thead><tbody>
          ${running.map(p => { const v = runView(p.run), s = v.steps[v.cur] || {}; return html`<tr data-run=${p.num}><td>${prCell(p)}</td><td class="whitespace-nowrap">${p.run.kind === 'fix' ? kind(p.run) : html`<a class="link" href=${'#/runs/' + p.run.id}>${kind(p.run)}</a>`}</td>
            <td><div class="flex items-center gap-2"><span class="pulse-dot"></span><span class="font-medium whitespace-nowrap">${s.label}</span><span class="text-ink3 text-xs trunc">${[s.units ? s.unit.replace('%d', s.du).replace('%d', s.units) : '', dur(v.real)].filter(Boolean).join(' · ')}</span></div><div class="bar mt-1.5"><i style=${{ width: Math.round(v.p * 100) + '%' }}></i></div></td>
            <td>${starter(p.run.by)}</td><td class="r font-medium">${money(v.cost)}</td><td class="r"><${Btn} sz="sm" v="danger-outline" icon="square" tip="Stops the agent now. Not signed." tipPos="left" onClick=${() => mutate(() => cancelRun(p))}>Cancel</${Btn}></td></tr>`; })}
          ${jobs.map(j => { const pp = Math.min(1, (Date.now() - j.startedAt) / j.sim); return html`<tr><td><a class="link font-medium" style="color:var(--text)" href=${'#/pr/' + j.pr}>${(S.prs[j.pr] || {}).title || 'PR #' + j.pr}</a> <span class="mono text-ink3">#${j.pr}</span></td><td>${j.type === 'analyst' ? 'Analyst' : html`<a class="link" href="#/settings/experiments">Trial · 2 rounds</a>`}</td>
            <td><div class="flex items-center gap-2"><span class="pulse-dot"></span><span class="font-medium">${j.type === 'analyst' ? 'Reading the closed PR' : pp < 0.5 ? 'Version A' : 'Version B'}</span><span class="text-ink3 text-xs">${dur(j.real * pp)}</span></div><div class="bar mt-1.5"><i style=${{ width: Math.round(pp * 100) + '%' }}></i></div></td><td>${starter(j.by)}</td><td class="r font-medium">${money(j.cost * pp)}</td><td></td></tr>`; })}
          ${queued.map(p => html`<tr data-queued=${p.num}><td>${prCell(p)}</td><td class="whitespace-nowrap">${kind(p.run)}</td><td><span class="inline-flex items-center gap-1.5 text-ink2"><${Icon} n="clock" s=${13} cls="text-ink3" />Waits: ${queueReason(p)}</span>${factoryStatus() !== 'running' && html` <button class="link bg-transparent border-0 p-0 ml-1" onClick=${openChip}>Open the status chip</button>`}</td><td>${starter(p.run.by)}</td><td class="r text-ink4">—</td><td class="r"><${Btn} sz="sm" icon="x" onClick=${() => mutate(() => cancelRun(p))}>Remove</${Btn}></td></tr>`)}
        </tbody></table></div>`}</section>
      <${Fold} hook="finished" title="Finished today" count=${today.length}>
        <div class="tblwrap mt-2"><table class="tbl"><thead><tr><th>Pull request</th><th>Run</th><th>Started by</th><th class="r">Cost</th><th class="r">Duration</th><th class="r">When</th></tr></thead><tbody>
          ${today.map(a => html`<tr class=${a.id && a.id[0] === 'r' && !/f/.test(a.id.slice(1)) ? 'click' : ''} onClick=${() => { if (getRunInfo(a.id)) nav('runs/' + a.id); }}><td><span class="font-medium">${(S.prs[a.pr] || {}).title}</span> <span class="mono text-ink3">#${a.pr}</span></td><td class="whitespace-nowrap">${a.what}${a.status === 'cancelled' ? html` <span class="text-ink3">· cancelled</span>` : a.status !== 'done' ? html` <span class="text-bad">· failed</span>` : ''}</td><td>${starter(a.by)}</td><td class="r">${money(a.cost)}</td><td class="r text-ink3">${dur(a.dur)}</td><td class="r text-ink3"><${Time} t=${a.at} /></td></tr>`)}
        </tbody></table></div></${Fold}>
    </div></main>`;
}

/* ---------- Insights ---------- */
const INS = (() => {
  const base = [7.9, 11.2, 9.4, 12.8, 8.1, 1.4, 0, 10.6, 13.9, 9.9, 12.1, 7.2, 0.9, 0, 8.8, 12.4, 10.1, 14.6, 9.3, 1.3, 0, 11.7, 9.8, 13.2, 8.4, 10.9, 0, 1.1, 12.3];
  return { days: base, byStage: [['Review', 108.62], ['Verify', 7.94], ['Fix check', 3.11], ['Implement', 1.24], ['Judge', 0.41], ['Analyst', 0.35]], byLevel: [['1 · Diff only', 71.2, '62 rounds'], ['2 · With context', 9.8, '7 rounds'], ['3 · Verified', 28.6, '19 rounds'], ['4 · Fix on request', 6.1, '4 rounds'], ['5 · Autofix', 4.3, '3 rounds'], ['6 · Learning', 1.67, '2 rounds']], byRepo: [['workflowbuilder', 115.6, '91 rounds'], ['wb-templates', 6.07, '6 rounds']] };
})();
function CostChart({ range }) {
  const [hov, setHov] = useState(null), [W, setW] = useState(920), box = useRef();
  useEffect(() => { const el = box.current, f = () => setW(Math.max(280, el.clientWidth)); f(); let ro; try { ro = new ResizeObserver(f); ro.observe(el); } catch (e) { window.addEventListener('resize', f); } return () => { ro ? ro.disconnect() : window.removeEventListener('resize', f); }; }, []);
  const vals = INS.days.slice(-(range - 1)).concat([S.factory.spent]), n = vals.length, H = 220, L = 40, B = 26, T = 10, max = Math.ceil(Math.max.apply(null, vals) / 5) * 5 || 5;
  const bw = (W - L - 8) / n, y = v => T + (H - T - B) * (1 - v / max), ticks = [0, max / 2, max];
  const date = i => Date.now() - (n - 1 - i) * DAY;
  const every = Math.ceil(n / Math.max(3, Math.floor((W - L) / 58)));
  return html`<div class="relative" ref=${box}><svg class="chart" viewBox=${'0 0 ' + W + ' ' + H} width=${W} height=${H} style="display:block" role="img" aria-label=${'Daily spend for the last ' + range + ' days'} onMouseLeave=${() => setHov(null)}>
    ${ticks.map(t => html`<line class="gridline" x1=${L} x2=${W} y1=${y(t)} y2=${y(t)} /><text x=${L - 8} y=${y(t) + 4} text-anchor="end">$${t}</text>`)}
    ${vals.map((v, i) => { const x = L + i * bw, h = Math.max(v > 0 ? 2 : 0, H - B - y(v)), w = Math.min(28, bw - 4), bx = x + (bw - w) / 2;
      return html`<g class="col" onMouseEnter=${() => setHov(i)}><rect class="hit" x=${x} y=${T} width=${bw} height=${H - T - B} /><path class=${cx('mark', hov != null && hov !== i && 'dim')} d=${h > 4 ? 'M' + bx + ',' + (H - B) + ' V' + (y(v) + 4) + ' q0,-4 4,-4 h' + (w - 8) + ' q4,0 4,4 V' + (H - B) + ' z' : 'M' + bx + ',' + (H - B) + ' v' + -h + ' h' + w + ' v' + h + ' z'} />
        ${(n - 1 - i) % every === 0 && html`<text x=${x + bw / 2} y=${H - 8} text-anchor="middle" style=${i === n - 1 ? 'font-weight:600;fill:var(--text)' : ''}>${i === n - 1 ? 'Today' : dayLabel(date(i))}</text>`}</g>`; })}
    <line class="axis" x1=${L} x2=${W} y1=${H - B} y2=${H - B} />
  </svg>
  ${hov != null && html`<div class="pop px-2.5 py-1.5 text-xs pointer-events-none" style=${{ left: Math.min(84, Math.max(4, (L + (hov + 0.5) * bw) / W * 100)) + '%', top: '4px', transform: 'translateX(-50%)', minWidth: 'auto' }}><div class="text-ink3">${hov === n - 1 ? 'Today' : dayLabel(date(hov))}</div><div class="num font-semibold text-sm">${money(vals[hov])}</div></div>`}</div>`;
}
function HBars({ rows }) { const max = Math.max.apply(null, rows.map(r => r[1])); return html`<div>${rows.map(([k, v, note]) => html`<div class="hbar" data-tip=${note || null}><span class="trunc text-ink2">${k}</span><span class="track"><i style=${{ width: Math.max(1, v / max * 100) + '%' }}></i></span><span class="num text-right font-medium">${money(v)}</span></div>`)}</div>`; }
function Stat({ label, value, sub }) { return html`<div class="card px-4 py-3"><div class="text-xs text-ink3">${label}</div><div class="num font-head font-semibold text-xl mt-0.5">${value}</div>${sub && html`<div class="text-xs text-ink3 mt-0.5">${sub}</div>`}</div>`; }
const NED = (have, unit) => html`<span class="text-ink4" data-tip=${'Shown from 5 ' + unit + ' up. Fewer would be noise.'}>Not enough data yet <span class="num">(${have} of 5)</span></span>`;
function InsightsPage({ route }) {
  const tab = route.path[1] || 'overview', [range, setRange] = useState(14);
  const total = INS.days.slice(-(range - 1)).reduce((a, b) => a + b, 0) + S.factory.spent;
  const pct = v => v == null ? '—' : Math.round(v * 100) + '%';
  const qLevels = [[1, 62, 171, null, null, 0.31, 1.15], [2, 7, 22, null, null, 0.36, 1.4], [3, 19, 64, 0.72, 0.11, 0.58, 1.51], [4, 4, 13, 0.77, 0.08, 0.69, 1.53], [5, 3, 7, 0.86, 0, 0.86, 1.43], [6, 2, 3, null, null, null, 0.84]];
  const qVers = [['review-rules.md', 'v3 · active', 37, 118, 0.74, 0.61, 1.38], ['review-rules.md', 'v2', 58, 201, 0.66, 0.44, 1.41], ['review-rules.md', 'v1', 41, 188, 0.52, 0.29, 1.52], ['verify-rules.md', 'v2 · active', 22, 71, 0.75, 0.6, 0.36], ['lessons.md', 'v2 · active', 19, 58, 0.78, 0.66, 1.36], ['review-rules.md (level 1 copy)', 'v1 · active', 96, 171, null, 0.31, 1.15], ['implement-rules.md', 'v1 · active', 6, 4, null, null, 0.11]];
  const shadow = [[265, 'would have fixed and pushed', true], [263, 'would have fixed and pushed', true], [270, 'would have fixed and pushed', true], [272, 'would have waited: 2 questions open', false], [269, 'would have waited: 1 finding not proven', false], [264, 'would have waited: patch touches a sensitive file', false], [239, 'would have waited: finding has no obvious fix', false], [271, 'would have waited: 1 finding not proven', false]];
  return html`<main class="gutter pb-24"><${PageHead} title="Insights" />
    <${Tabs} label="Insights sections" value=${tab} onChange=${t => nav('insights/' + t)} tabs=${[{ id: 'overview', label: 'Overview', icon: 'gauge' }, { id: 'cost', label: 'Cost', icon: 'wallet' }, { id: 'quality', label: 'Quality', icon: 'badge-check' }, { id: 'trust', label: 'Trust ladder', icon: 'layers' }]} />
    ${tab === 'overview' && html`<${Overview} q=${route.q} />`}
    ${tab === 'cost' && html`<div class="grid gap-4 mt-4">
      <div class="grid gap-3 grid-cols-2 lg:grid-cols-4"><${Stat} label="Spent today" value=${money(S.factory.spent)} sub=${'of ' + money(S.factory.budget) + ' daily budget'} /><${Stat} label=${'Last ' + range + ' days'} value=${money(total)} sub="all repositories" /><${Stat} label="Average round" value="$1.36" sub="2 min 31 s" /><${Stat} label="Share spent on Review" value="89%" /></div>
      <section class="card"><div class="card-h"><h2 class="card-t m-0">Spend by day</h2><div class="seg" role="group" aria-label="Time range">${[7, 14, 30].map(r => html`<button aria-pressed=${String(range === r)} onClick=${() => setRange(r)}>${r} days</button>`)}</div></div><div class="p-4"><${CostChart} range=${range} /></div></section>
      <div class="grid gap-4 lg:grid-cols-3 items-start"><section class="card"><div class="card-h"><h2 class="card-t m-0">By repository</h2><span class="text-xs text-ink3">last 14 days</span></div><div class="px-4 py-3"><${HBars} rows=${INS.byRepo} /></div></section>
        <section class="card"><div class="card-h"><h2 class="card-t m-0">By stage</h2><span class="text-xs text-ink3">last 14 days</span></div><div class="px-4 py-3"><${HBars} rows=${INS.byStage} /></div></section>
        <section class="card"><div class="card-h"><h2 class="card-t m-0">By review level</h2><span class="text-xs text-ink3">last 14 days</span></div><div class="px-4 py-3"><${HBars} rows=${INS.byLevel} /></div></section></div>
    </div>`}
    ${tab === 'quality' && html`<div class="grid gap-4 mt-4">
      <section><h2 class="sec-t m-0 mb-2">Per review level<${Info} pos="right" tip="Confirmed and Refuted come from the verifier (level 3 and up). Decided Implement is the share of decided findings that people chose to fix: the best sign that findings are useful. A rate is shown only from 5 findings up." /></h2><div class="tblwrap"><table class="tbl"><thead><tr><th>Level</th><th class="r">Rounds</th><th class="r">Findings</th><th class="r">Confirmed</th><th class="r">Refuted</th><th class="r">Decided Implement</th><th class="r">Average round</th></tr></thead><tbody>
        ${qLevels.map(([n, rounds, fN, conf, ref, acc, avg]) => html`<tr><td><span class="font-medium">${n} · ${LEVELS[n - 1].name}</span></td><td class="r">${rounds}</td><td class="r">${fN}</td>${fN < 5 ? html`<td class="r" colspan="3">${NED(fN, 'findings')}</td>` : html`<td class="r">${n < 3 ? html`<span class="text-ink4" data-tip="Levels 1–2 do not verify findings.">Unchecked</span>` : pct(conf)}</td><td class="r">${n < 3 ? html`<span class="text-ink4">Unchecked</span>` : pct(ref)}</td><td class="r font-medium">${pct(acc)}</td>`}<td class="r">${money(avg)}</td></tr>`)}
      </tbody></table></div></section>
      <section><h2 class="sec-t m-0 mb-2">Per instruction version</h2><div class="tblwrap"><table class="tbl"><thead><tr><th>Instruction</th><th>Version</th><th class="r">Runs</th><th class="r">Findings</th><th class="r">Confirmed</th><th class="r">Decided Implement</th><th class="r">Average cost</th></tr></thead><tbody>
        ${qVers.map(([f, v, runs, fN, conf, acc, avg]) => html`<tr><td class="mono">${f}</td><td>${v}</td><td class="r">${runs}</td><td class="r">${fN}</td>${fN < 5 ? html`<td class="r" colspan="2">${NED(fN, 'findings')}</td>` : html`<td class="r">${conf == null ? html`<span class="text-ink4">Unchecked</span>` : pct(conf)}</td><td class="r font-medium">${pct(acc)}</td>`}<td class="r">${money(avg)}</td></tr>`)}
        ${S.instructions.filter(f => f.draft).map(f => html`<tr><td class="mono">${f.name}</td><td>v${f.draft.n} · draft</td><td class="r">0</td><td class="r">0</td><td class="r" colspan="2">${NED(0, 'findings')}</td><td class="r">—</td></tr>`)}
      </tbody></table></div></section></div>`}
    ${tab === 'trust' && html`<div class="grid gap-4 mt-4">
      ${Object.values(S.repos).map(rp => { const L = rp.defaultLevel, wb = rp.name === WB; return html`<section class="card"><div class="card-h flex-wrap"><h2 class="card-t m-0">${rp.name}<${Info} pos="right" tip="A repository earns a higher review level when people keep agreeing with what the current level finds." /></h2><a class="link text-xs" href=${'#/settings/repos/' + repoShort(rp.name)}>Change the level</a></div>
        <div class="p-4 grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
          <div><div class="flex items-center gap-1.5 flex-wrap">${LEVELS.map(l => html`<div class=${cx('flex items-center gap-1.5 px-2 py-1.5 rounded-lg border text-xs', l.n === L ? 'border-brand bg-brandbg font-semibold' : l.n < L ? 'border-line' : 'border-dashed border-line text-ink3')} data-tip=${l.desc}><span class=${cx('lvl', l.n <= L && 'on')} style="width:22px;height:22px;font-size:12px">${l.n}</span>${l.name}</div>`)}</div>
            <div class="mt-3 text-sm">${wb ? html`<span class="font-semibold">Level 3 for 14 days:</span> 58% of decided findings were Implement, 72% confirmed by the verifier, 11% refuted. <span class="text-ink3">Based on 64 findings in 19 rounds.</span>` : html`<span class="font-semibold">Level 1 for 11 days:</span> ${NED(3, 'decided findings')}`}</div>
            ${wb && html`<div class="text-sm text-ink2 mt-2 flex items-start gap-2"><${Icon} n="arrow-up" s=${14} cls="text-ink3 mt-0.5" /><span>Next: level 4. On 4 trial PRs, people pushed 3 of 3 patches without edits.</span></div>`}</div>
          <div><div class="blk-t">Level 5 shadow log</div>${wb ? html`<div class="text-sm"><span class="font-semibold">Level 5 would have fixed 3 of 8 PRs</span> <span class="text-ink3">· last 14 days</span><${Info} tip="Nothing was pushed: this is only a log of what autofix would have done." /></div>
            <ul class="m-0 p-0 list-none mt-2 divide border border-div rounded-lg">${shadow.map(([n, t, ok]) => html`<li class="flex items-center gap-2 px-3 py-1.5 text-sm"><${Icon} n=${ok ? 'circle-check' : 'circle-dashed'} s=${14} cls=${ok ? 'text-ok' : 'text-ink3'} /><a class="link mono" href=${'#/pr/' + n}>#${n}</a><span class=${ok ? '' : 'text-ink2'}>${t}</span></li>`)}</ul>` : html`<div class="text-sm text-ink4">Not enough data yet <span class="num">(2 of 5 PRs)</span><${Info} tip="The shadow log needs verified findings, so it starts at level 3." /></div>`}</div>
        </div></section>`; })}
    </div>`}
  </main>`;
}
